using System;
using UnityEngine;

namespace TamTam.Vfx
{
    public enum VfxShape { Dot, Sparkle, Leaf, Ring, Puff, Rune, Shard }

    /// Particle materials (one per shape and blend), generated by TamTam ▸ VFX ▸ Generar biblioteca and loaded from
    /// Resources so runtime code never needs Shader.Find. Additive = HDR light (bloom); alpha = matter (smoke, leaves).
    [CreateAssetMenu(menuName = "TamTam/VFX Library")]
    public class VfxLibrary : ScriptableObject
    {
        [Serializable] public class Entry { public VfxShape shape; public Material additive, alpha; }
        public Entry[] entries;

        static VfxLibrary instance;
        public static VfxLibrary Instance => instance ? instance : instance = Resources.Load<VfxLibrary>("TamTamVfx");

        public Material Get(VfxShape s, bool additive)
        {
            foreach (var e in entries) if (e.shape == s) return additive ? e.additive : e.alpha;
            return null;
        }
    }
}
